import { createEntryPayload } from "./page";

export const EntriesPage = () => {
  const payload = createEntryPayload({
    entryId: "entry-1",
    name: "Draft",
    tags: ["new"],
    enabled: true,
  });

  return <pre>{JSON.stringify(payload)}</pre>;
};

/**
 * @summary 엔트리 생성 요청 payload 계약
 */
export interface CreateEntryPayload {
  /**
   * @field 생성할 엔트리 ID
   */
  entryId: string;
  /**
   * @field 화면에서 입력한 엔트리 이름
   */
  name: string;
  /**
   * @field 엔트리에 연결할 태그 목록
   */
  tags: string[];
  /**
   * @field 엔트리 활성화 여부
   */
  enabled: boolean;
}

/**
 * @helper 엔트리 생성 화면의 입력을 요청 payload로 정규화
 */
export const createEntryPayload = (
  payload: CreateEntryPayload,
): CreateEntryPayload => {
  const { entryId, name, tags, enabled } = payload;

  return {
    entryId,
    name: name.trim(),
    tags,
    enabled,
  };
};
